<script setup>
import {ref,onBeforeUnmount} from 'vue';
defineProps({src:String,alt:{type:String,default:'查看图片'},preview:{type:Boolean,default:true}});
const dialog=ref(null),closing=ref(false);let timer,previous;
function show(){previous=document.activeElement;dialog.value.showModal();document.documentElement.classList.add('image-open');}
function close(){if(closing.value)return;closing.value=true;timer=setTimeout(()=>{dialog.value?.close();closing.value=false;document.documentElement.classList.remove('image-open');previous?.focus();},180);}
onBeforeUnmount(()=>{clearTimeout(timer);document.documentElement.classList.remove('image-open');});
</script>
<template><button v-if="preview" type="button" class="lin-image-trigger" :aria-label="alt" @click="show"><img :src="src" :alt="alt" loading="lazy"/><span>查看原图 ↗</span></button><img v-else :src="src" :alt="alt" class="lin-image-static" loading="lazy"/><Teleport to="body"><dialog ref="dialog" class="lin-lightbox" :class="{closing}" aria-label="图片预览" @cancel.prevent="close" @click.self="close"><div class="lightbox-content"><button type="button" class="lightbox-close" aria-label="关闭图片预览" autofocus @click="close">✕</button><img :src="src" :alt="alt"/><p>{{alt}}</p></div></dialog></Teleport></template>
<style>
.lin-image-trigger{position:relative;width:100%;height:100%;display:block;border:0;padding:0;background:transparent;cursor:zoom-in;overflow:hidden}.lin-image-trigger>img,.lin-image-static{width:100%;height:100%;object-fit:cover;display:block;transition:transform .6s}.lin-image-trigger:hover>img{transform:scale(1.045)}.lin-image-trigger>span{position:absolute;bottom:10px;right:12px;background:#182331b8;color:white;padding:5px 8px;font-size:10px;border-radius:4px;opacity:0;transition:opacity .2s}.lin-image-trigger:hover>span,.lin-image-trigger:focus-visible>span{opacity:1}html.image-open{overflow:hidden}.lin-lightbox{position:fixed;inset:0;width:100vw;max-width:none;height:100dvh;max-height:none;padding:60px 24px;margin:0;border:0;background:transparent;color:white;box-sizing:border-box;z-index:99999}.lin-lightbox[open]{display:grid;place-items:center;animation:lightbox-show .2s ease-out}.lin-lightbox::backdrop{background:#10151be6;backdrop-filter:blur(8px)}.lightbox-content{position:relative;max-width:1100px;max-height:100%;min-width:0;pointer-events:none}.lightbox-content>img{display:block;max-width:100%;max-height:calc(100dvh - 150px);object-fit:contain;border-radius:6px;box-shadow:0 20px 80px #0005;pointer-events:auto}.lightbox-content>p{font-size:12px;line-height:1.8;opacity:.8;margin:12px 0}.lightbox-close{position:absolute;right:0;top:-45px;border:1px solid #ffffff70;background:#141923;color:white;width:36px;height:36px;border-radius:50%;cursor:pointer;pointer-events:auto}.lin-lightbox.closing{animation:lightbox-hide .18s ease-in forwards}@keyframes lightbox-show{from{opacity:0;transform:translateY(12px) scale(.98)}to{opacity:1;transform:none}}@keyframes lightbox-hide{to{opacity:0;transform:scale(.98)}}@media(prefers-reduced-motion:reduce){.lin-lightbox[open],.lin-lightbox.closing{animation:none}.lin-image-trigger>img{transition:none}}
</style>
